#import <Foundation/Foundation.h>
#import <CoreGraphics/CoreGraphics.h>
#import "../RWDetailPresentation.h"
#import "../RWPreviewSession.h"
static CGRect Frame(NSArray *v){return CGRectMake([v[0]doubleValue],[v[1]doubleValue],[v[2]doubleValue],[v[3]doubleValue]);}
int main(void){@autoreleasepool{
    __block int checks=0,failures=0;void(^check)(BOOL,NSString *)=^(BOOL ok,NSString *label){checks++;if(!ok){failures++;fprintf(stderr,"FAIL %s\n",label.UTF8String);}};
    NSDictionary *movie=@{@"name":@"An actual film",@"type":@"movie",@"releaseInfo":@"2026",@"runtime":@"127 min",@"imdbRating":@"8.1",@"genres":@[@"Drama",@"Mystery",@"Drama"]};NSDictionary *text=[RWDetailPresentation textForMeta:movie rating:@{@"label":@"PG-13"}];
    check([text[@"kind"]isEqual:@"FILM"]&&[text[@"facts"]containsString:@"2026"]&&[text[@"facts"]containsString:@"2h 7m"],@"Film facts identify type, year and readable runtime");check([text[@"rating"]isEqual:@"IMDb 8.1"]&&[text[@"facts"]containsString:@"PG-13"],@"IMDb score and age classification retain separate meanings");check([text[@"genres"]isEqual:@"Drama · Mystery"],@"Genres stay concise and unique");
    NSDictionary *show=@{@"type":@"series",@"name":@"An actual show",@"releaseInfo":@"2003–2015",@"videos":@[@{@"season":@1},@{@"season":@1},@{@"season":@2},@{@"season":@0},@{@"season":NSNull.null}],@"imdbRating":@"N/A"};text=[RWDetailPresentation textForMeta:show rating:@{}];check([text[@"kind"]isEqual:@"SERIES"]&&[text[@"facts"]containsString:@"2 seasons"],@"Series facts count distinct listed seasons and exclude specials");check(![text[@"rating"]length],@"Missing score does not become a zero or fabricated match");
    for(id score in @[@"8.3 rubbish",@"NaN",@11,NSNull.null]){NSMutableDictionary *invalid=[movie mutableCopy];invalid[@"imdbRating"]=score;check(![[RWDetailPresentation textForMeta:invalid rating:@{}][@"rating"]length],@"Malformed or out-of-range ratings stay absent");}
    for(NSNumber *width in @[@768,@900,@1024]){NSDictionary *layout=[RWDetailPresentation layoutForWidth:width.doubleValue];CGRect media=Frame(layout[@"media"]),title=Frame(layout[@"title"]),facts=Frame(layout[@"facts"]),rating=Frame(layout[@"rating"]),genres=Frame(layout[@"genres"]);CGFloat height=[layout[@"height"]doubleValue];
        check(fabs(media.size.width/media.size.height-16.0/9)<.0001&&media.size.width>=480&&media.size.height>=270,@"Native and official embedded trailers receive an actual 16:9 viewport");
        check(!CGRectIntersectsRect(media,title)&&!CGRectIntersectsRect(media,facts)&&!CGRectIntersectsRect(media,rating),@"Title, facts and rating never cover provider controls or video");
        check(!CGRectIntersectsRect(title,facts)&&!CGRectIntersectsRect(rating,genres),@"Text and score slots do not overlap");
        check(CGRectGetMaxY(genres)<=height&&CGRectGetMaxY(media)<=height&&CGRectGetMaxX(media)<=width.doubleValue,@"Header bounds include media and metadata in both orientations");
        check([[RWDetailPresentation layoutForWidth:width.doubleValue]isEqual:layout],@"Metadata arrival cannot change reserved header geometry");
    }
    RWPreviewSession *session=[RWPreviewSession new];[session selectKey:@"adult:movie:tt1"];NSUInteger initial=session.generation;check([session.state isEqual:@"waiting"],@"New title visit waits for visible eligibility");
    check(![session beginAllowed:YES visible:NO manual:NO]&&session.generation==initial,@"Offscreen title does not begin lookup");check(![session beginAllowed:NO visible:YES manual:NO],@"Autoplay preference is respected");
    check([session beginAllowed:YES visible:YES manual:NO],@"Visible eligible title begins once");NSUInteger generation=session.generation;
    [session selectKey:@"adult:movie:tt1"];check(session.generation==generation&&[session.state isEqual:@"lookup"],@"Late metadata and layout selection preserve an in-flight lookup");
    check(![session beginAllowed:YES visible:YES manual:NO],@"Repeated rendering cannot duplicate lookup");check([session acceptSource:YES generation:generation]&&[session.state isEqual:@"loading"],@"Only current lookup attaches a source");check(![session acceptSource:YES generation:generation],@"Duplicate completion cannot create a second player");
    check([session event:@"playing" generation:generation]&&![session beginAllowed:YES visible:YES manual:NO],@"Playing preview cannot be restarted by metadata");
    check([session event:@"ended" generation:generation]&&![session beginAllowed:YES visible:YES manual:NO],@"Ended preview returns to artwork without an automatic replay loop");check(![session event:@"playing" generation:generation],@"Late frame cannot revive a finished preview");
    check([session beginAllowed:NO visible:YES manual:YES],@"Explicit playback can retry a terminal preview even with autoplay disabled");generation=session.generation;[session acceptSource:YES generation:generation];[session event:@"unavailable" generation:generation];check(![session beginAllowed:YES visible:YES manual:NO],@"Failure does not relaunch on each scroll callback");
    [session selectKey:@"kids:movie:tt1"];check(![session acceptSource:YES generation:generation]&&[session.state isEqual:@"waiting"],@"Cross-profile lookup result is stale");[session beginAllowed:YES visible:YES manual:NO];generation=session.generation;[session cancel];check(![session acceptSource:YES generation:generation]&&[session.state isEqual:@"idle"],@"Back or Play invalidates pending results");
    [session selectKey:@"adult:series:tt2"];[session beginAllowed:YES visible:YES manual:NO];generation=session.generation;[session acceptSource:NO generation:generation];check([session.state isEqual:@"unavailable"]&&! [session beginAllowed:YES visible:YES manual:NO],@"Missing source keeps artwork for the rest of this visit");
    [session cancel];[session selectKey:@"adult:series:tt2"];[session beginAllowed:YES visible:YES manual:NO];generation=session.generation;[session event:@"released" generation:generation];check(![session acceptSource:YES generation:generation]&&! [session beginAllowed:YES visible:YES manual:NO],@"Background or memory release cannot be undone by a late callback");
    [session cancel];[session selectKey:@"adult:movie:tt3"];[session beginAllowed:YES visible:YES manual:NO];generation=session.generation;[session acceptSource:YES generation:generation];check([session beginNativeFallback]&&session.generation!=generation,@"Embedded failure may try one native source within this visit");
    check(![session event:@"playing" generation:generation],@"Old embedded callbacks cannot attach during native fallback");generation=session.generation;check([session acceptSource:YES generation:generation],@"Native fallback completion owns the new generation");check(![session beginNativeFallback]&&[session.diagnostics[@"native_fallbacks"]intValue]==1,@"Provider fallback is bounded to one, not a retry loop");
    [session event:@"unavailable" generation:generation];check(![session beginAllowed:YES visible:YES manual:NO],@"A failed native fallback settles on artwork");
    printf("{\"checks\":%d,\"failures\":%d}\n",checks,failures);return failures?1:0;
}}
